window.ZfcInflate=async data=>new Response(new Blob([Uint8Array.from(atob(data),c=>c.charCodeAt(0))]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();
window.ZfcVendorReady=window.ZfcInflate('').then(buffer=>{const script=document.createElement('script');script.textContent=new TextDecoder().decode(buffer);document.head.append(script);script.remove()});
